package sg.safelease.app;
import java.util.Map;import org.json.*;
/** Human-readable labels follow the app language; originals and manifest facts remain unchanged. */
final class EvidencePdf {
 final MainActivity owner;final boolean chinese;final JSONObject copy;
 EvidencePdf(MainActivity owner)throws Exception{this.owner=owner;chinese="zh".equals(owner.pref("language"));copy=new JSONObject(owner.asset("android-ui-copy.json"));}
 String t(String en,String zh){return chinese?zh:en;}
 String value(String raw){JSONArray pair=copy.optJSONArray(raw);if(pair!=null)return pair.optString(chinese?1:0,raw);if(raw.startsWith("Version dispute "))return t("Version dispute ","版本异议 ")+raw.substring(16);return raw;}
 byte[] renderLetter(JSONObject manifest)throws Exception{MainActivity.PdfWriter w=new MainActivity.PdfWriter();try{JSONObject draft=manifest.optJSONObject("letter_draft");if(draft==null||draft.optString("letter").trim().isEmpty())throw new IllegalArgumentException("letter_draft_required");w.line("SafeLease SG");w.line(t("Letter draft - complete and send yourself","信函草稿 — 请自行填写发送"));w.line(draft.getString("letter"));w.line(t("Attachment checklist (files are exported separately): ","附件清单（文件需另行导出）：")+draft.getJSONArray("attachments").toString().replace("movein",t("Move-in record","入住记录")).replace("moveout",t("Move-out record","退租记录")));w.line(t("General information, not legal advice. SafeLease does not hold or transfer funds.","一般信息，非法律意见。SafeLease不保管或转移资金。"));return w.finish();}finally{w.close();}}
 byte[] render(JSONObject manifest,Map<String,byte[]> originals)throws Exception{
  MainActivity.PdfWriter w=new MainActivity.PdfWriter();try{
   JSONObject l=manifest.getJSONObject("lease");w.line("SafeLease SG");w.line(t("Rental evidence","租住证据"));w.line(t("Lease: ","租约：")+l.getString("id"));w.line(value(l.getString("address")));
   w.line(t("Deposit: ","押金：")+l.getLong("deposit_cents")/100.0+t("; returned: ","；已退：")+l.getLong("returned_cents")/100.0+t("; outstanding: ","；未退：")+l.getLong("outstanding_cents")/100.0);
   w.line(t("Contract refund date: ","合同退款日：")+l.getString("refund_date"));w.line(t("Receipt times originate on this phone and are not independently verified.","收件时间来自本机，未经独立核实。"));
   JSONArray records=l.getJSONArray("records");
   for(int i=0;i<records.length();i++){JSONObject record=records.getJSONObject(i);JSONArray versions=record.getJSONArray("versions");for(int j=versions.length()-1;j>=0;j--){JSONObject v=versions.getJSONObject(j);w.next();w.line(value(record.getString("kind"))+" "+t("v","版本")+v.getInt("seq"));w.line(t("Version: ","版本标识：")+v.getString("id"));w.line(t("Digest: ","摘要：")+v.getString("digest"));w.line(t("Status: ","状态：")+value(v.getString("status"))+("bilateral".equals(v.getString("status"))?"":t(" - NOT BILATERAL"," — 非双方确认")));w.line(t("48-hour window opened: ","四十八小时窗口开始时间：")+v.getLong("opened")+t("; deadline: ","；截止时间：")+v.getLong("deadline"));
    JSONObject body=v.getJSONObject("body");w.line(value(body.optString("note")));JSONArray decisions=v.getJSONArray("decisions");for(int k=0;k<decisions.length();k++){JSONObject d=decisions.getJSONObject(k);w.line(value(d.optString("role"))+" / "+value(d.optString("name"))+": "+value(d.optString("kind"))+" @ "+d.optLong("created")+" "+value(d.optString("note")));}
    JSONArray photos=body.getJSONArray("photos");for(int k=0;k<photos.length();k++){JSONObject p=photos.getJSONObject(k);w.line(t("Photo: ","照片：")+p.getString("id")+" / "+value(p.getString("room")));w.line("SHA-256 "+p.getString("sha256"));w.line(t("Local receipt: ","本机收件：")+p.optLong("received")+t("; device claim: ","；设备声明：")+p.optString("capture_claim"));w.line(t("Paired move-in: ","入住对照：")+p.optString("paired_with"));w.line(value(p.optString("note")));JSONArray metas=manifest.getJSONArray("photos");for(int n=0;n<metas.length();n++){JSONObject meta=metas.getJSONObject(n);if(meta.getString("id").equals(p.getString("id"))&&!meta.isNull("filename"))w.image(originals.get(meta.getString("filename")));}}
   }}
   JSONObject savedLetter=manifest.optJSONObject("letter_draft");if(savedLetter!=null&&!savedLetter.optString("letter").trim().isEmpty()){w.next();w.line(t("Saved letter draft - complete and send yourself","已保存信函草稿 — 请自行填写发送"));w.line(savedLetter.optString("letter"));w.line(t("General information, not legal advice. SafeLease does not hold or transfer funds.","一般信息，非法律意见。SafeLease不保管或转移资金。"));}
   w.next();w.line(t("Listing checks","房源检查"));JSONArray checks=manifest.getJSONArray("checks");for(int i=0;i<checks.length();i++){JSONObject check=checks.getJSONObject(i);w.line(value(check.optString("kind"))+" / "+value(check.optString("status")));w.line(value(check.optString("source")));w.line(check.optString("object"));w.line(t("Checked at: ","检查时间：")+check.optLong("created"));JSONObject result=new JSONObject(check.optString("result","{}"));w.line(value(result.optString("note")));w.line(value(result.optString("limitation")));}
   w.line(t("Human review","人工复核"));JSONArray cases=manifest.getJSONArray("cases");for(int i=0;i<cases.length();i++){JSONObject c=cases.getJSONObject(i);w.line(value(c.optString("subject"))+" / "+value(c.optString("status")));JSONArray replies=c.optJSONArray("replies");if(replies!=null)for(int j=0;j<replies.length();j++){JSONObject reply=replies.getJSONObject(j);w.line(reply.optString("author")+" @ "+reply.optLong("created")+": "+value(reply.optString("body")));}}
   w.line(t("Legal source: ","法律资料：")+"https://www.judiciary.gov.sg/civil/cases-eligible-small-claim");w.line(t("This record does not establish ownership, identity or legal admissibility.","本记录不证明产权、身份或司法采纳。"));return w.finish();
  }finally{w.close();}
 }
}
